/*
 * A295008  Numbers whose square has largest digit 8.
 * https://oeis.org/A295008
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   numbers whose square has largest decimal digit 8. No closed‑form
 *            known – the terms are generated by a linear search and memoised
 * Range:     u8 n <= 36, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   has_largest_digit_8
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/has_largest_digit_8.h"

/* Cache for previously found terms */
static seq_t *cache     = NULL;
static size_t cache_len = 0;
static size_t cache_cap = 0;
static idx_t next_candidate = 1;

/* Ensure cache has space for another term. */
static void grow_cache(void)
{
    if (cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 128;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        cache     = tmp;
        cache_cap = new_cap;
    }
}

/* Generate the n-th term (n >= 1).  The function is thread‑unsafe
   but meets the required behaviour. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;           /* undefined for n=0 */

    /* Extend the cache until it contains the first n terms. */
    while (cache_len < (size_t)n) {
        idx_t cand = next_candidate++;
        if (has_largest_digit_8(cand)) {
            grow_cache();
            cache[cache_len++] = (seq_t)cand;
        }
    }
    return cache[n - 1];
}
